<?php
/**  * Module Configuration Management  * Provides database-driven configuration for system modules  */  class ModuleConfig {  private static $config = null;  private static $pdo = null;  /**  * Initialize module configuration with database values  */  private static function init() {  global $pdo;  self::$pdo = $pdo;  // Create config tables if not exist  self::createConfigTables();  // Load configuration  self::loadConfig();  }  /**  * Create module configuration tables  */  private static function createConfigTables() {  // Modules table - tracks which modules are enabled/disabled  $modulesSql = "CREATE TABLE IF NOT EXISTS module_settings (  id INT AUTO_INCREMENT PRIMARY KEY,  module_key VARCHAR(100) UNIQUE NOT NULL,  module_name VARCHAR(200) NOT NULL,  module_description TEXT,  is_enabled TINYINT(1) DEFAULT 1,  module_order INT DEFAULT 0,  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP  )";  // Module configuration table - stores module-specific settings  $configSql = "CREATE TABLE IF NOT EXISTS module_config (  id INT AUTO_INCREMENT PRIMARY KEY,  module_key VARCHAR(100) NOT NULL,  config_key VARCHAR(100) NOT NULL,  config_value TEXT NOT NULL,  config_type VARCHAR(20) DEFAULT 'string',  config_category VARCHAR(50) DEFAULT 'general',  description TEXT,  is_encrypted TINYINT(1) DEFAULT 0,  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,  UNIQUE KEY unique_module_config (module_key, config_key),  FOREIGN KEY (module_key) REFERENCES module_settings(module_key) ON DELETE CASCADE  )";  // Module audit trail table  $auditSql = "CREATE TABLE IF NOT EXISTS module_config_audit (  id INT AUTO_INCREMENT PRIMARY KEY,  module_key VARCHAR(100) NOT NULL,  config_key VARCHAR(100),  action_type ENUM('enable', 'disable', 'update', 'create') NOT NULL,  old_value TEXT,  new_value TEXT,  changed_by INT NOT NULL,  changed_by_role VARCHAR(50) NOT NULL,  ip_address VARCHAR(45),  user_agent TEXT,  timestamp TIMESTAMP DEFAULT CURRENT_TIMESTAMP,  INDEX idx_module_key (module_key),  INDEX idx_timestamp (timestamp)  )";  try {  self::$pdo->exec($modulesSql);  self::$pdo->exec($configSql);  self::$pdo->exec($auditSql);  self::insertDefaultModules();  } catch (Exception $e) {  error_log("Module Config table creation error: " . $e->getMessage());  }  }  /**  * Insert default modules and configurations  */  private static function insertDefaultModules() {  // Default modules  $defaultModules = [  'transactions' => [  'name' => 'Transactions',  'description' => 'Point of Sale and transaction management system',  'enabled' => 1,  'order' => 1,  'settings' => [  'auto_pull_enabled' => ['value' => '1', 'type' => 'boolean', 'category' => 'logic', 'desc' => 'Enable automatic data pulling for transactions'],  'auto_pull_interval' => ['value' => '30', 'type' => 'integer', 'category' => 'logic', 'desc' => 'Auto-pull interval in seconds'],  'computation_formula' => ['value' => '(present - previous - calibration) * price_per_liter', 'type' => 'string', 'category' => 'formula', 'desc' => 'Fuel transaction computation formula'],  'max_transaction_amount' => ['value' => '10000', 'type' => 'decimal', 'category' => 'validation', 'desc' => 'Maximum transaction amount allowed'],  'require_manager_approval' => ['value' => '0', 'type' => 'boolean', 'category' => 'approval', 'desc' => 'Require manager approval for transactions above threshold']  ]  ],  'job_orders' => [  'name' => 'Job Orders',  'description' => 'Service and maintenance job order management',  'enabled' => 1,  'order' => 2,  'settings' => [  'auto_assign_jobs' => ['value' => '0', 'type' => 'boolean', 'category' => 'logic', 'desc' => 'Enable automatic job assignment'],  'job_status_workflow' => ['value' => 'pending,in_progress,completed,cancelled', 'type' => 'string', 'category' => 'workflow', 'desc' => 'Job order status workflow (comma-separated)'],  'auto_complete_hours' => ['value' => '24', 'type' => 'integer', 'category' => 'logic', 'desc' => 'Hours after which jobs are auto-completed'],  'priority_levels' => ['value' => 'low,medium,high,urgent', 'type' => 'string', 'category' => 'classification', 'desc' => 'Job priority levels']  ]  ],  'fuel_management' => [  'name' => 'Fuel Management',  'description' => 'Fuel inventory, readings, and reconciliation system',  'enabled' => 1,  'order' => 3,  'settings' => [  'auto_pull_readings' => ['value' => '1', 'type' => 'boolean', 'category' => 'logic', 'desc' => 'Enable automatic fuel readings pulling'],  'calibration_formula' => ['value' => 'present - previous', 'type' => 'string', 'category' => 'formula', 'desc' => 'Calibration computation formula'],  'low_stock_threshold' => ['value' => '500', 'type' => 'decimal', 'category' => 'alert', 'desc' => 'Low stock alert threshold in liters'],  'critical_stock_threshold' => ['value' => '200', 'type' => 'decimal', 'category' => 'alert', 'desc' => 'Critical stock alert threshold in liters'],  'reconciliation_tolerance' => ['value' => '5', 'type' => 'decimal', 'category' => 'validation', 'desc' => 'Reconciliation tolerance percentage']  ]  ],  'calendar' => [  'name' => 'Calendar',  'description' => 'Shift scheduling and calendar management',  'enabled' => 1,  'order' => 4,  'settings' => [  'auto_schedule_shifts' => ['value' => '0', 'type' => 'boolean', 'category' => 'logic', 'desc' => 'Enable automatic shift scheduling'],  'shift_duration_hours' => ['value' => '8', 'type' => 'integer', 'category' => 'scheduling', 'desc' => 'Default shift duration in hours'],  'max_shifts_per_day' => ['value' => '3', 'type' => 'integer', 'category' => 'scheduling', 'desc' => 'Maximum shifts per day'],  'advance_booking_days' => ['value' => '30', 'type' => 'integer', 'category' => 'booking', 'desc' => 'Days in advance for shift booking']  ]  ],  'reports' => [  'name' => 'Reports',  'description' => 'System reports, analytics, and compliance documentation',  'enabled' => 1,  'order' => 5,  'settings' => [  'auto_generate_reports' => ['value' => '1', 'type' => 'boolean', 'category' => 'automation', 'desc' => 'Enable automatic report generation'],  'report_retention_days' => ['value' => '365', 'type' => 'integer', 'category' => 'retention', 'desc' => 'Number of days to retain reports'],  'audit_log_retention_days' => ['value' => '730', 'type' => 'integer', 'category' => 'retention', 'desc' => 'Number of days to retain audit logs'],  'export_formats' => ['value' => 'pdf,excel,csv', 'type' => 'string', 'category' => 'export', 'desc' => 'Available export formats (comma-separated)'],  'compliance_check_enabled' => ['value' => '1', 'type' => 'boolean', 'category' => 'compliance', 'desc' => 'Enable compliance checking']  ]  ],  'inventory' => [  'name' => 'Inventory',  'description' => 'Merchandise and fuel inventory management, stock requests, and history',  'enabled' => 1,  'order' => 6,  'settings' => [  'low_stock_alert_enabled' => ['value' => '1', 'type' => 'boolean', 'category' => 'alert', 'desc' => 'Enable low stock alerts'],  'low_stock_threshold_qty' => ['value' => '10', 'type' => 'integer', 'category' => 'alert', 'desc' => 'Low stock alert threshold (units)'],  'stock_request_approval' => ['value' => '1', 'type' => 'boolean', 'category' => 'approval', 'desc' => 'Require manager approval for stock requests'],  'auto_deduct_on_sale' => ['value' => '1', 'type' => 'boolean', 'category' => 'logic', 'desc' => 'Automatically deduct inventory on sale'],  'track_inventory_history' => ['value' => '1', 'type' => 'boolean', 'category' => 'logic', 'desc' => 'Track full inventory change history']  ]  ],  'customers' => [  'name' => 'Customers',  'description' => 'Customer management, loyalty, balances, and transaction linkage',  'enabled' => 1,  'order' => 7,  'settings' => [  'loyalty_program_enabled' => ['value' => '1', 'type' => 'boolean', 'category' => 'loyalty', 'desc' => 'Enable customer loyalty program'],  'credit_limit_default' => ['value' => '5000', 'type' => 'decimal', 'category' => 'credit', 'desc' => 'Default customer credit limit'],  'require_customer_on_sale' => ['value' => '0', 'type' => 'boolean', 'category' => 'validation', 'desc' => 'Require customer linkage on every sale'],  'balance_alert_threshold' => ['value' => '1000', 'type' => 'decimal', 'category' => 'alert', 'desc' => 'Outstanding balance alert threshold']  ]  ],  'deliveries' => [  'name' => 'Deliveries',  'description' => 'Fuel and merchandise delivery management, validation, and oversight',  'enabled' => 1,  'order' => 8,  'settings' => [  'require_manager_validation' => ['value' => '1', 'type' => 'boolean', 'category' => 'approval', 'desc' => 'Require manager validation for deliveries'],  'auto_update_inventory' => ['value' => '1', 'type' => 'boolean', 'category' => 'logic', 'desc' => 'Auto-update inventory on delivery confirmation'],  'delivery_variance_tolerance' => ['value' => '2', 'type' => 'decimal', 'category' => 'validation', 'desc' => 'Delivery quantity variance tolerance (%)'],  'require_supplier_confirmation' => ['value' => '0', 'type' => 'boolean', 'category' => 'approval', 'desc' => 'Require supplier confirmation before processing']  ]  ],  'purchase_orders' => [  'name' => 'Purchase Orders',  'description' => 'Purchase order creation, approval workflow, and supplier management',  'enabled' => 1,  'order' => 9,  'settings' => [  'require_admin_approval' => ['value' => '1', 'type' => 'boolean', 'category' => 'approval', 'desc' => 'Require admin approval for purchase orders'],  'auto_generate_po_number' => ['value' => '1', 'type' => 'boolean', 'category' => 'logic', 'desc' => 'Auto-generate purchase order numbers'],  'po_expiry_days' => ['value' => '30', 'type' => 'integer', 'category' => 'validation', 'desc' => 'Purchase order expiry in days'],  'max_po_amount' => ['value' => '500000', 'type' => 'decimal', 'category' => 'validation', 'desc' => 'Maximum purchase order amount']  ]  ],  'staff_management' => [  'name' => 'Staff Management',  'description' => 'Staff oversight, attendance, performance tracking, and shift management',  'enabled' => 1,  'order' => 10,  'settings' => [  'track_attendance' => ['value' => '1', 'type' => 'boolean', 'category' => 'attendance', 'desc' => 'Enable staff attendance tracking'],  'overtime_threshold_hours' => ['value' => '8', 'type' => 'integer', 'category' => 'scheduling', 'desc' => 'Daily hours threshold before overtime'],  'performance_review_enabled' => ['value' => '1', 'type' => 'boolean', 'category' => 'performance', 'desc' => 'Enable staff performance reviews'],  'max_staff_per_shift' => ['value' => '5', 'type' => 'integer', 'category' => 'scheduling', 'desc' => 'Maximum staff per shift']  ]  ],  'admin_unlock' => [  'name' => 'Admin Unlock',  'description' => 'Admin-level unlock for locked transactions, voided entries, and override approvals',  'enabled' => 1,  'order' => 11,  'settings' => [  'unlock_requires_reason' => ['value' => '1', 'type' => 'boolean', 'category' => 'validation', 'desc' => 'Require reason for every unlock action'],  'unlock_audit_enabled' => ['value' => '1', 'type' => 'boolean', 'category' => 'audit', 'desc' => 'Log all unlock actions to audit trail'],  'max_unlocks_per_day' => ['value' => '10', 'type' => 'integer', 'category' => 'validation', 'desc' => 'Maximum unlock actions per admin per day'],  'notify_superadmin_on_unlock' => ['value' => '0', 'type' => 'boolean', 'category' => 'notification', 'desc' => 'Notify SuperAdmin when unlock is performed']  ]  ]  ];  try {  // Insert modules  foreach ($defaultModules as $moduleKey => $moduleData) {  $stmt = self::$pdo->prepare("INSERT IGNORE INTO module_settings (module_key, module_name, module_description, is_enabled, module_order) VALUES (?, ?, ?, ?, ?)");  $stmt->execute([$moduleKey, $moduleData['name'], $moduleData['description'], $moduleData['enabled'], $moduleData['order']]);  // Insert module settings  foreach ($moduleData['settings'] as $configKey => $configData) {  $stmt = self::$pdo->prepare("INSERT IGNORE INTO module_config (module_key, config_key, config_value, config_type, config_category, description) VALUES (?, ?, ?, ?, ?, ?)");  $stmt->execute([  $moduleKey,  $configKey,  $configData['value'],  $configData['type'],  $configData['category'],  $configData['desc']  ]);  }  }  } catch (Exception $e) {  error_log("Failed to insert default modules: " . $e->getMessage());  }  }  /**  * Load configuration from database  */  private static function loadConfig() {  try {  // Load modules  $stmt = self::$pdo->query("SELECT module_key, module_name, module_description, is_enabled, module_order FROM module_settings ORDER BY module_order");  self::$config['modules'] = $stmt->fetchAll(PDO::FETCH_ASSOC);  // Load module configurations  $stmt = self::$pdo->query("SELECT * FROM module_config ORDER BY module_key, config_category, config_key");  self::$config['settings'] = $stmt->fetchAll(PDO::FETCH_ASSOC);  } catch (Exception $e) {  error_log("Failed to load module config: " . $e->getMessage());  self::$config = ['modules' => [], 'settings' => []];  }  }  /**  * Get all modules  */  public static function getModules() {  if (self::$config === null) {  self::init();  }  return self::$config['modules'];  }  /**  * Get enabled modules only  */  public static function getEnabledModules() {  if (self::$config === null) {  self::init();  }  return array_filter(self::$config['modules'], function($module) {  return $module['is_enabled'] == 1;  });  }  /**  * Get module by key  */  public static function getModule($moduleKey) {  if (self::$config === null) {  self::init();  }  foreach (self::$config['modules'] as $module) {  if ($module['module_key'] === $moduleKey) {  return $module;  }  }  return null;  }  /**  * Check if module is enabled  */  public static function isModuleEnabled($moduleKey) {  $module = self::getModule($moduleKey);  return $module && $module['is_enabled'] == 1;  }  /**  * Get module settings  */  public static function getModuleSettings($moduleKey) {  if (self::$config === null) {  self::init();  }  $settings = [];  foreach (self::$config['settings'] as $setting) {  if ($setting['module_key'] === $moduleKey) {  $settings[] = $setting;  }  }  return $settings;  }  /**  * Get specific module setting  */  public static function getModuleSetting($moduleKey, $configKey, $default = null) {  if (self::$config === null) {  self::init();  }  foreach (self::$config['settings'] as $setting) {  if ($setting['module_key'] === $moduleKey && $setting['config_key'] === $configKey) {  return self::parseConfigValue($setting['config_value'], $setting['config_type']);  }  }  return $default;  }  /**  * Parse configuration value based on type  */  private static function parseConfigValue($value, $type) {  switch ($type) {  case 'boolean':  return (bool)$value;  case 'integer':  return (int)$value;  case 'decimal':  return (float)$value;  case 'array':  return explode(',', $value);  default:  return $value;  }  }  /**  * Enable/disable module  */  public static function setModuleStatus($moduleKey, $enabled, $userId, $userRole) {  if (self::$config === null) {  self::init();  }  try {  $stmt = self::$pdo->prepare("UPDATE module_settings SET is_enabled = ?, updated_at = CURRENT_TIMESTAMP WHERE module_key = ?");  $stmt->execute([$enabled ? 1 : 0, $moduleKey]);  // Log to audit trail  self::logModuleChange($moduleKey, null, $enabled ? 'enable' : 'disable', null, $enabled, $userId, $userRole);  // Update cached config  foreach (self::$config['modules'] as &$module) {  if ($module['module_key'] === $moduleKey) {  $module['is_enabled'] = $enabled ? 1 : 0;  break;  }  }  return true;  } catch (Exception $e) {  error_log("Failed to update module status: " . $e->getMessage());  return false;  }  }  /**  * Update module setting  */  public static function updateModuleSetting($moduleKey, $configKey, $newValue, $userId, $userRole) {  if (self::$config === null) {  self::init();  }  try {  // Get old value for audit  $oldValue = self::getModuleSetting($moduleKey, $configKey);  $stmt = self::$pdo->prepare("UPDATE module_config SET config_value = ?, updated_at = CURRENT_TIMESTAMP WHERE module_key = ? AND config_key = ?");  $stmt->execute([$newValue, $moduleKey, $configKey]);  // Log to audit trail  self::logModuleChange($moduleKey, $configKey, 'update', $oldValue, $newValue, $userId, $userRole);  // Update cached config  foreach (self::$config['settings'] as &$setting) {  if ($setting['module_key'] === $moduleKey && $setting['config_key'] === $configKey) {  $setting['config_value'] = $newValue;  break;  }  }  return true;  } catch (Exception $e) {  error_log("Failed to update module setting: " . $e->getMessage());  return false;  }  }  /**  * Log module configuration changes to audit trail  */  private static function logModuleChange($moduleKey, $configKey, $action, $oldValue, $newValue, $userId, $userRole) {  try {  $stmt = self::$pdo->prepare("INSERT INTO module_config_audit (module_key, config_key, action_type, old_value, new_value, changed_by, changed_by_role, ip_address, user_agent) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)");  $stmt->execute([  $moduleKey,  $configKey,  $action,  is_string($oldValue) ? $oldValue : json_encode($oldValue),  is_string($newValue) ? $newValue : json_encode($newValue),  $userId,  $userRole,  $_SERVER['REMOTE_ADDR'] ?? 'unknown',  $_SERVER['HTTP_USER_AGENT'] ?? 'unknown'  ]);  } catch (Exception $e) {  error_log("Failed to log module change: " . $e->getMessage());  }  }  /**  * Get audit trail for module  */  public static function getModuleAuditTrail($moduleKey = null, $limit = 100) {  if (self::$config === null) {  self::init();  }  try {  $sql = "SELECT mca.*, u.username FROM module_config_audit mca LEFT JOIN users u ON mca.changed_by = u.id WHERE 1=1";  $params = [];  if ($moduleKey) {  $sql .= " AND mca.module_key = ?";  $params[] = $moduleKey;  }  $sql .= " ORDER BY mca.timestamp DESC LIMIT " . (int)$limit;  $stmt = self::$pdo->prepare($sql);  $stmt->execute($params);  return $stmt->fetchAll(PDO::FETCH_ASSOC);  } catch (Exception $e) {  error_log("Failed to get module audit trail: " . $e->getMessage());  return [];  }  }  /**  * Get settings grouped by category for a module  */  public static function getModuleSettingsByCategory($moduleKey) {  $settings = self::getModuleSettings($moduleKey);  $grouped = [];  foreach ($settings as $setting) {  $category = $setting['config_category'];  if (!isset($grouped[$category])) {  $grouped[$category] = [];  }  $grouped[$category][] = $setting;  }  return $grouped;  }
}
?>
